"""Tests for user_auth registration and authentication logic.

Run from the project root with:

    python -m unittest discover -s tests -v
"""

import sys
import tempfile
import unittest
from pathlib import Path

# Make the project root importable when tests run from anywhere.
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

import user_auth  # noqa: E402


class HashTest(unittest.TestCase):
    def test_hash_round_trip(self):
        stored = user_auth.hash_password("hunter2")
        self.assertTrue(user_auth.verify_password("hunter2", stored))
        self.assertFalse(user_auth.verify_password("hunter3", stored))

    def test_hashes_are_salted(self):
        self.assertNotEqual(
            user_auth.hash_password("same-password"),
            user_auth.hash_password("same-password"),
        )

    def test_verify_rejects_garbage(self):
        self.assertFalse(user_auth.verify_password("x", "not-a-valid-hash"))


class DatabaseTest(unittest.TestCase):
    """Each test runs against its own throwaway database file."""

    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.db_path = Path(self._tmp.name) / "test.db"
        self.conn = user_auth.connect(self.db_path)

    def tearDown(self):
        self.conn.close()
        self._tmp.cleanup()

    def test_register_then_login_by_username_and_email(self):
        user_id = user_auth.register_user(
            self.conn, "alice", "alice@example.com", "correct horse battery staple"
        )
        self.assertIsInstance(user_id, int)
        self.assertTrue(
            user_auth.authenticate_user(self.conn, "alice", "correct horse battery staple")
        )
        self.assertTrue(
            user_auth.authenticate_user(
                self.conn, "alice@example.com", "correct horse battery staple"
            )
        )

    def test_wrong_password_rejected(self):
        user_auth.register_user(self.conn, "bob", "bob@example.com", "right-password")
        self.assertFalse(
            user_auth.authenticate_user(self.conn, "bob", "wrong-password")
        )

    def test_unknown_user_rejected(self):
        self.assertFalse(
            user_auth.authenticate_user(self.conn, "ghost", "whatever")
        )

    def test_duplicate_email_rejected(self):
        user_auth.register_user(self.conn, "carol", "carol@example.com", "password-one")
        with self.assertRaises(ValueError):
            user_auth.register_user(
                self.conn, "carol2", "carol@example.com", "password-two"
            )

    def test_duplicate_username_rejected(self):
        user_auth.register_user(self.conn, "dave", "dave@example.com", "password-one")
        with self.assertRaises(ValueError):
            user_auth.register_user(
                self.conn, "dave", "dave2@example.com", "password-two"
            )

    def test_password_is_not_stored_in_plaintext(self):
        user_auth.register_user(self.conn, "erin", "erin@example.com", "super-secret-123")
        row = self.conn.execute(
            "SELECT password_hash FROM users WHERE username = ?", ("erin",)
        ).fetchone()
        self.assertNotIn("super-secret-123", row["password_hash"])
        self.assertIn("$", row["password_hash"])


if __name__ == "__main__":
    unittest.main()

